using System.Windows;using OdinVault.Manager.Wpf.ViewModels;namespace OdinVault.Manager.Wpf.Views;public partial class StorageView:System.Windows.Controls.UserControl{public StorageView(){InitializeComponent();}async void Edit_Click(object s,RoutedEventArgs e){if(DataContext is not StorageViewModel vm||vm.Selected is null){MessageBox.Show("ابتدا یک مقصد ذخیره‌سازی را انتخاب کنید.","OdinVault");return;}var dialog=new StorageTargetEditWindow(vm.Selected){Owner=Window.GetWindow(this)};if(dialog.ShowDialog()!=true)return;try{await vm.Client.UpdateStorageAsync(vm.Selected.Id,dialog.Request);await vm.LoadAsync();MessageBox.Show("تغییرات مقصد ذخیره شد.","OdinVault");}catch(Exception ex){MessageBox.Show(ex.Message,"OdinVault");}}}